/* ---- film 115 helpers ---- */
const S115 = K115.s, L115 = K115.L;
const B115 = { m: 0.8, th: 0.9 }, BE115 = { th: 2.1 };
function interp115(arr, x) { if (x <= arr[0][0]) return arr[0][1]; for (let i = 1; i < arr.length; i++) if (x <= arr[i][0]) { const f = (x - arr[i - 1][0]) / (arr[i][0] - arr[i - 1][0]); return arr[i - 1][1] * (1 - f) + arr[i][1] * f; } return arr[arr.length - 1][1]; }
function sstep115(x) { x = clamp(x); return x * x * (3 - 2 * x); }
/* core wave 2 Re(b e^(i s l)) and exterior wave c 2 Re(beta e^(i s (l - T))) for the illustrative phases */
