    plotAxes(px, py, pw, ph, pq, 'a', 'ψ(a) , sample n = 2 , g = 8');
    curve(p => { const an = -Math.PI / 2 + p * Math.PI; return [xS(an), yS(interp115(PSI_115, an))]; }, 120, C.gold, pq, 3.5);
    lbl('ψ(0) = 0.6749', xS(0), yS(0.6749) + 30, C.gold, pq, 15); lbl('ψ(±π/2) = 0.8570', xS(Math.PI / 2) - 4, yS(0.857) - 14, C.gold, pq, 15, 'right');
    lbl('(A − (g/2π) Q₂) ψ = −s² C ψ ,  C[ψ] = 1 ,  m_ψ = ‖ψ‖²_(L²(da)) = 1.6908', 470, 570, C.white, pq, 15);
