  pro.forEach((s, i) => { const qq = clamp(q0 * 1.6 - i / 6); check115(185, 322 + i * 58, C.green, qq); lblG(s, 215, 330 + i * 58, C.white, qq, 18, 'left'); });
  const mq = Q(S, 0, 'nothing yet makes it little o of root E', 0.6);
  box(990, 240, 780, 330, C.red, mq, 2, 'rgba(40,0,10,0.3)'); lbl('MISSING', 1380, 275, C.red, mq, 18);
