  mis.forEach(([s, ph], i) => { const qq = clamp(Q(S, 0, ph, 0.6) * 1.6 - i / 6); cross115(1025, 322 + i * 58, C.red, qq); lblG(s, 1055, 330 + i * 58, C.white, qq, 18, 'left'); });
